Item.method_code:
const consumeLicenseResult = aras.ConsumeLicense('Aras.PublishingService');

if (consumeLicenseResult.isError) {
	if (consumeLicenseResult.errorMessage.indexOf('FeatureHasNoLicensesException') > -1 ||
		consumeLicenseResult.errorMessage.indexOf('FeatureLicenseValidationException') > -1) {
		const advertisingUrl = aras.getResource('../Modules/aras.innovator.TDF', 'techdoc.advertising_url');
		aras.AlertWarning(aras.getResource('../Modules/aras.innovator.TDF', 'techdoc.advertising_message', advertisingUrl));
	} else {
		aras.AlertError(consumeLicenseResult.errorMessage);
	}
	return;
}

if (aras.isTempEx(this.node) || aras.isDirtyEx(this.node)) {
	if (aras.confirm(aras.getResource('../Modules/aras.innovator.TDF', 'publishing.need2save_item'))) {
		const itemId = this.getID();
		const result = aras.saveItemEx(this.node);
		if (result === null) {
			return;
		}
		if (typeof window.item !== 'function') {
			window.item = result;
		}
		aras.uiReShowItemEx(itemId, result);
	} else {
		return;
	}
}

const type = this.getAttribute('type');
let itemTypeSettings = aras.newIOMItem(type, 'tdf_GetItemTypeSettings');
itemTypeSettings = itemTypeSettings.apply();

const formId = itemTypeSettings.getProperty('publishing.dialogFormId');
const optionFamiliesBuilderMethod = itemTypeSettings.getProperty('datamodel.filterFamiliesGetter');
const contentBuilderMethod = itemTypeSettings.getProperty('datamodel.documentContentGetter');

const dialogParameters = {
	title: aras.getResource('../Modules/aras.innovator.TDF', 'includes.publishingdialog'),
	formId, // tp_PublishingForm by default
	aras: aras,
	parentWindow: window,
	// server method that returns list of option families as string in JSON format
	// {"familyName1": ["value1","value2",..], "familyName2":["value3","value4",..]}
	optionFamiliesBuilderMethod,
	// option families also can be passed from here with following parameter
	// optionFamilies: {firstFamily: ["value1,value2,.."], secondFamily:["value3","value4",..]}
	isEditMode: true,
	documentItem: this,
	dialogWidth: 340, dialogHeight: 500, resizable: false,
	content: 'ShowFormAsADialog.html',
	contentBuilderMethod
};
window.ArasModules.Dialog.show('iframe', dialogParameters);
return true;
